// Normalise an arbitrary staff-uploaded sheet into the Leads schema.
//
// Staff paste whatever their source gave them — "Company name", "First name", "Email address",
// "Website". This maps those onto canonical fields WITHOUT an LLM call in the common case: a
// deterministic alias table is instant, free, auditable, and cannot hallucinate a mapping. The
// model is a fallback for headers this table has never seen, not the first move.
//
// CONTROL COLUMNS are ours and are never treated as data.
const CONTROL = new Set(['status', 'notes', 'mapped_lead_id', 'row_number', 'source_config',
                         'Product', 'product']);

// The two products this engine can pitch. A lead has to be one or the other, and only a human can
// say which: `source_config` records how the lead ARRIVED (Apollo / Warmly-Intent / Referral /
// Manual) and says nothing about who should be pitching them. Added 2026-08-29 — before this the
// runner had 'oryoniq' hardcoded, so a council CIO typed in for VisioneerIT would have been sent
// GovCon capture copy signed OryonIQ.
const PRODUCTS = { oryoniq: 'OryonIQ', visioneerit: 'VisioneerIT' };
const resolveProduct = (v) => PRODUCTS[String(v == null ? '' : v).toLowerCase().replace(/[^a-z]/g, '')] || '';

// BATCH CAP. A real upload is 49,000 rows — reading and mapping all of them in one execution
// would blow memory and, worse, hand 49,000 rows to the downstream sheet write at once. Capped
// per cycle; the poll simply picks up the next batch two minutes later, so a large upload drains
// steadily instead of failing all at once.
const MAX_PER_CYCLE = 50;

const ALIASES = {
  contact_email: ['email', 'emailaddress', 'workemail', 'businessemail', 'contactemail',
                  'primaryemail', 'mail', 'emailid', 'eaddress', 'personalemail'],
  first_name:    ['firstname', 'fname', 'givenname', 'first', 'forename'],
  last_name:     ['lastname', 'lname', 'surname', 'familyname', 'last'],
  _full_name:    ['fullname', 'name', 'contactname', 'leadname', 'personname', 'contact'],
  company:       ['company', 'companyname', 'organization', 'organisation', 'org', 'account',
                  'accountname', 'employer', 'business', 'firm'],
  title:         ['title', 'jobtitle', 'position', 'role', 'designation', 'jobrole', 'jobposition'],
  company_domain:['domain', 'companydomain', 'website', 'websiteurl', 'url', 'web', 'companyurl',
                  'site', 'companywebsite'],
  linkedin_url:  ['linkedin', 'linkedinurl', 'linkedinprofile', 'liprofile', 'profileurl', 'li'],
  phone:         ['phone', 'phonenumber', 'mobile', 'mobilenumber', 'telephone', 'tel',
                  'directdial', 'cell', 'cellphone'],
};

// Compared after stripping everything that is not a letter or digit, so "E-mail Address",
// "email_address" and "Email Address" all collapse to the same key.
const norm = (s) => String(s === undefined || s === null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const LOOKUP = {};
for (const [field, names] of Object.entries(ALIASES)) for (const n of names) LOOKUP[n] = field;

const CTRL_CHARS = /[�-]+/g;
const clean = (v, cap) => {
  const n = cap || 200;
  if (typeof v === 'number') return String(v);
  if (typeof v !== 'string') return '';
  return v.replace(CTRL_CHARS, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
};
const EMAIL = /^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/;

// Real uploads arrive SHOUTING: ROBERT, NATHANIEL, TRUSTED SOLUTIONS LLC. Interpolated straight
// into a greeting that becomes "Hi ROBERT," which reads as shouting at a stranger. Only rewritten
// when the value has no lowercase at all, so McDonald and O'Brien and IBM-style names that were
// typed correctly are left exactly as they are.
// Entity suffixes and common acronyms stay upper — "Trusted Solutions Llc" is worse than the
// shouting it replaced, and it is the company name a prospect sees written about their own firm.
const KEEP_UPPER = new Set(['LLC','L.L.C','INC','LLP','PLLC','PC','LP','LTD','PLC','CO','CORP',
  'USA','US','IT','AI','HR','IP','GSA','DOD','LLC.','INC.','SA','NV','BV','GMBH','AG','PBC']);
const fixCase = (s) => {
  if (!s || /[a-z]/.test(s)) return s;
  return s.replace(/[A-Za-z][A-Za-z'\u2019.-]*/g, (w) => {
    const bare = w.replace(/[.,]+$/, '');
    if (KEEP_UPPER.has(bare)) return w;
    if (bare.length <= 1) return w;
    return w.charAt(0) + w.slice(1).toLowerCase();
  });
};

const rows = $input.all().map((i) => i.json || {});
const out = [];
const seenEmails = new Set();

for (const r of rows) {
  if (out.length >= MAX_PER_CYCLE) break;
  if (clean(r.status)) continue;                    // already handled; blank is the claim marker

  const dataKeys = Object.keys(r).filter((k) => !CONTROL.has(k));
  if (!dataKeys.some((k) => clean(r[k]))) continue; // blank spacer row

  const mapped = {};
  const unmapped = [];
  for (const key of dataKeys) {
    const field = LOOKUP[norm(key)];
    const val = clean(r[key]);
    if (!field) { if (val) unmapped.push(key); continue; }
    if (val && !mapped[field]) mapped[field] = val;  // first non-empty wins
  }

  // A single "Full Name" column is common and useless unsplit — the opener greets a first name.
  if (!mapped.first_name && mapped._full_name) {
    const parts = mapped._full_name.split(/\s+/).filter(Boolean);
    if (parts.length) mapped.first_name = parts[0];
    if (parts.length > 1 && !mapped.last_name) mapped.last_name = parts.slice(1).join(' ');
  }
  delete mapped._full_name;

  mapped.first_name = fixCase(mapped.first_name);
  mapped.last_name = fixCase(mapped.last_name);
  mapped.company = fixCase(mapped.company);

  if (mapped.company_domain) {
    mapped.company_domain = mapped.company_domain
      .replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
  }
  if (mapped.contact_email) mapped.contact_email = mapped.contact_email.toLowerCase();

  // STILL BEING TYPED? Leave it entirely alone — do not map it, do not claim it, do not flag it.
  //
  // This polls every two minutes while a human types a row cell by cell. Without this, a row that
  // has a name but no address yet is read mid-edit, marked needs_review, and CLAIMED — so when the
  // person finishes typing the address nothing ever looks at it again. Their row silently never
  // imports and they have no idea why.
  //
  // An address is the one field that is never plausibly "not typed yet but coming" in a row that
  // is otherwise finished: a staff member filling a lead has the email in front of them, it is
  // usually pasted, and a row with a name but no address is far more likely half-written than
  // genuinely broken. So no address means "not ready", not "invalid" — and the row stays
  // untouched until an address appears.
  //
  // A row that HAS an address and is still wrong is genuinely incomplete, and is flagged normally.
  //
  // ONE EXCEPTION, and it is the whole reason the model fallback exists: a sheet whose email
  // column is named something the alias table has never seen ("Contact Point", "Reach") also
  // arrives here with no address. That is not a half-typed row — it is a row whose address is
  // sitting in a column nobody recognised. Unmapped headers are what tell the two apart:
  //   no address, no unknown columns  -> still being typed, leave it alone
  //   no address, unknown columns     -> the address may be in one of them, ask the model
  if (!mapped.contact_email && unmapped.length === 0) continue;

  // What a lead REQUIRES to be run: an address to write to, a name to greet, a company to talk
  // about. Anything less produces an email addressed to nobody about nothing.
  // Which product is this person going to hear from? Refuse rather than guess: a wrong guess puts
  // the wrong company's pitch in front of a real person and cannot be taken back, while a refused
  // row costs somebody ten seconds with a dropdown.
  const productRaw = clean(r.Product !== undefined ? r.Product : r.product, 40);
  const product = resolveProduct(productRaw);

  const problems = [];
  if (!product) {
    problems.push(productRaw
      ? `'${productRaw}' is not a product — choose OryonIQ or VisioneerIT`
      : 'Product is blank — choose OryonIQ or VisioneerIT');
  }
  if (!mapped.contact_email) problems.push('no email column found');
  else if (!EMAIL.test(mapped.contact_email)) problems.push(`'${mapped.contact_email}' is not a single valid address`);
  else if (seenEmails.has(mapped.contact_email)) problems.push('duplicate address earlier in this upload');
  if (!mapped.first_name) problems.push('no first name found');
  if (!mapped.company) problems.push('no company found');

  // Worth surfacing rather than fixing: a first name that does not appear in the address at all
  // often means the row pairs one person's name with another's email. Seen in a real upload —
  // "ANGELA SPEASE" against Kevin.Spease@. Not fatal, and not something to guess at, but the
  // human importing 49,000 rows should be told.
  const warnings = [];
  if (mapped.contact_email && mapped.first_name && EMAIL.test(mapped.contact_email)) {
    const local = mapped.contact_email.split('@')[0].toLowerCase();
    const fn = mapped.first_name.toLowerCase();
    if (fn.length > 2 && !local.includes(fn) && !local.includes(fn.slice(0, 3))) {
      warnings.push(`first name "${mapped.first_name}" does not appear in the address — check the row pairs the right person`);
    }
  }

  if (mapped.contact_email && EMAIL.test(mapped.contact_email)) seenEmails.add(mapped.contact_email);

  out.push({ json: Object.assign({}, mapped, {
    row_number: r.row_number === undefined ? null : r.row_number,
    source_config: clean(r.source_config) || 'Manual',
    Product: product,
    _raw: r,
    _unmapped_headers: unmapped,
    _problems: problems,
    _warnings: warnings,
    // The model is needed only when a REQUIRED field is still missing AND there are unrecognised
    // headers that might contain it. No unknown headers means the model cannot help, so no call.
    _needs_llm: problems.length > 0 && unmapped.length > 0,
    _ok: problems.length === 0,
  }) });
}
return out;

// Ask the model to map ONLY the headers the alias table did not recognise, and only for rows where
// a required field is still missing. One call per such row — never for the common case.
const r = $input.item.json;
return { json: Object.assign({}, r, {
  _prompt: 'Map these spreadsheet column headers onto canonical lead fields.\n'
    + 'Canonical fields: contact_email, first_name, last_name, company, title, company_domain, '
    + 'linkedin_url, phone.\n'
    + 'Reply with ONLY a JSON object mapping header -> field. Omit any header that does not '
    + 'clearly correspond to one of those fields. Never invent a field name.\n\n'
    + 'Headers: ' + JSON.stringify(r._unmapped_headers),
}) };

// Apply the model's proposed mapping, then RE-VALIDATE from scratch.
//
// The model's answer is a suggestion about column NAMES only. It never decides whether a row is
// usable — the same required-field check runs again afterwards — and a mapping onto a field that
// does not exist is discarded rather than written.
const CANON = new Set(['contact_email','first_name','last_name','company','title',
                       'company_domain','linkedin_url','phone']);
const EMAIL = /^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/;
const clean = (v, cap) => (typeof v === 'string'
  ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, cap || 200) : '');

const src = $('Shape AI prompt').first().json;
const r = Object.assign({}, src);
let proposed = {};
try {
  const raw = $input.item.json?.message?.content
    ?? $input.item.json?.choices?.[0]?.message?.content
    ?? $input.item.json?.text ?? '';
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (m) proposed = JSON.parse(m[0]);
} catch (e) { proposed = {}; }

const applied = [];
for (const [header, field] of Object.entries(proposed)) {
  if (!CANON.has(field)) continue;          // invented field -> discard
  if (r[field]) continue;                   // alias table already found it -> keep that
  const val = clean((r._raw || {})[header]);
  if (!val) continue;
  r[field] = field === 'contact_email' ? val.toLowerCase() : val;
  applied.push(header + ' -> ' + field);
}

const problems = [];
if (!r.contact_email) problems.push('no email column found');
else if (!EMAIL.test(r.contact_email)) problems.push("'" + r.contact_email + "' is not a single valid address");
if (!r.first_name) problems.push('no first name found');
if (!r.company) problems.push('no company found');

return { json: Object.assign({}, r, { _problems: problems, _ok: problems.length === 0,
                                      _llm_applied: applied, _llm_used: true }) };

// Shape the lead for VERIFICATION, not for the sheet. Changed 2026-08-29.
//
// This used to write straight into `Leads`. That skipped the only stage that checks whether an
// address is real, whether we already hold it, and whether the person has asked us to stop —
// so every lead a human typed went round the outside of Reoon, the dedupe check and the
// suppression list. Now it hands the batch to VIO-intake-verify-curate, which owns all three.
//
// `channel_state_email` is deliberately NOT set here any more: intake writes the Leads row, and
// two writers stamping the same lifecycle column is how a row ends up disagreeing with itself.
//
// `inbox_row` and `_inbox` ride along so the verdict can be reported back onto the row a human is
// watching. Identity does NOT survive an Execute Workflow call by itself — intake echoes
// `inbox_row` back deliberately, and `_inbox` never leaves this workflow at all: the merge node
// reads it from THIS node's output, not from anything intake returns.
const r = $input.item.json;
return { json: {
  email: r.contact_email,
  contact_email: r.contact_email,
  first_name: r.first_name || '', last_name: r.last_name || '',
  company: r.company || '', title: r.title || '', company_domain: r.company_domain || '',
  linkedin_url: r.linkedin_url || '', phone: r.phone || '',
  has_email: Boolean(r.contact_email), has_phone: Boolean(r.phone),
  source_config: r.source_config || 'Manual',
  Product: r.Product || '',
  inbox_row: r.row_number === undefined ? null : r.row_number,
  _inbox: {
    row_number: r.row_number === undefined ? null : r.row_number,
    llm_used: r._llm_used === true,
    llm_applied: r._llm_applied || [],
    warnings: r._warnings || [],
    unmapped_headers: r._unmapped_headers || [],
  },
} };

// Write the outcome back onto the Inbox row a human is watching. A row is NEVER silently dropped:
// if it could not be imported the row says why, and names the headers nobody recognised.
//
// Since 2026-08-29 this reports the VERIFICATION result too, not just the column mapping. The
// distinction matters to whoever pasted the list: "we could not read your columns" and "that
// address is not real" are different problems with different fixes, and lumping both under
// needs_review taught staff nothing.
const r = $input.item.json;
const ok = r._ok === true;
const outcome = r._verify_outcome || '';
const bits = [];
if (r._llm_used) bits.push((r._llm_applied || []).length
  ? 'AI mapped: ' + r._llm_applied.join(', ')
  : 'AI could not map the remaining headers');
if (ok && outcome === 'needs_review') {
  bits.push('Imported, but check before sending — ' + (r._verify_reason || 'verification was not conclusive'));
} else if (ok && r._reoon_status) {
  bits.push('Address verified (' + r._reoon_status + ')');
}
if (!ok) bits.push('Not imported — ' + (r._problems || []).join('; '));
for (const w of (r._warnings || [])) bits.push('Check: ' + w);
if ((r._unmapped_headers || []).length) bits.push('Unrecognised columns: ' + r._unmapped_headers.join(', '));

// A row verification could not finish is left UNCLAIMED so the next cycle retries it. Claiming it
// would mean a Reoon outage silently discarded the row — the human would see a blank status
// forever and never learn why. Everything else is claimed exactly as before.
const retry = outcome === 'verify_failed' || outcome === 'no_verdict';
return { json: {
  row_number: r.row_number,
  status: retry ? '' : (ok ? 'mapped' : 'needs_review'),
  notes: bits.join(' | ').slice(0, 900),
  mapped_lead_id: ok ? (r.contact_email || '') : '',
} };

// Put each verification verdict back on the Inbox row it came from.
//
// Two sources, and they are joined on the Inbox row number rather than on the email address:
//   * `$input` — what intake returned. One item per lead, carrying `inbox_row` because intake
//     echoes it back. Nothing else about a lead survives an Execute Workflow call.
//   * `$('Shape Lead row')` — this workflow's own memory of what it sent, including the mapping
//     diagnostics (`_inbox`) that intake never sees and does not care about.
//
// A lead that intake returns NO verdict for is the dangerous case: it means the batch went in and
// something came back that does not account for it. It is reported as unverified with that said
// out loud, never as a success.
const R = (v) => (typeof v === 'string' ? v : v == null ? '' : String(v));

const verdicts = new Map();
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.inbox_row === null || j.inbox_row === undefined) continue;
  verdicts.set(String(j.inbox_row), j);
}

const out = [];
for (const it of $('Shape Lead row').all()) {
  const sent = it.json || {};
  const meta = sent._inbox || {};
  const v = verdicts.get(String(sent.inbox_row));

  // pass          -> verified, written to Leads, ready to run
  // needs_review  -> written to Leads but a human should look before it sends
  // drop          -> undeliverable; deliberately NOT in Leads
  // skipped       -> duplicate or on the suppression list; costs nothing, sends nothing
  // verify_failed -> Reoon did not answer; the lead is unprocessed and should be retried
  const outcome = v ? R(v.outcome) : 'no_verdict';
  const imported = outcome === 'pass' || outcome === 'needs_review';

  out.push({ json: {
    row_number: meta.row_number === undefined ? null : meta.row_number,
    contact_email: sent.contact_email || '',
    _ok: imported,
    _llm_used: meta.llm_used === true,
    _llm_applied: meta.llm_applied || [],
    _warnings: meta.warnings || [],
    _unmapped_headers: meta.unmapped_headers || [],
    _problems: imported ? [] : [
      outcome === 'drop' ? `address rejected by verification (${R(v.reoon_status) || 'undeliverable'})`
      : outcome === 'skipped' ? `not imported — ${R(v.reason) || 'already held, or on the suppression list'}`
      : outcome === 'verify_failed' ? 'verification did not complete — left for the next run, nothing was sent'
      : 'verification returned no verdict for this row — left unprocessed',
    ],
    _verify_outcome: outcome,
    _verify_reason: v ? R(v.reason) : '',
    _reoon_status: v ? R(v.reoon_status) : '',
  }});
}
return out;
